      this.target[0] + this.dist * Math.cos(this.pitch) * Math.sin(this.yaw),
      this.target[1] - this.dist * Math.cos(this.pitch) * Math.cos(this.yaw),
      this.target[2] + this.dist * Math.sin(this.pitch),
    ]
